function matchesType(v, type, pmType, matchesTraits) {
    if (type === "unknown") return true;
    if (typeof v === type) return true;
    if (typeof v === "object" && v) {
        if (v.customId === pmType) return true
        if (v.customId === "vgsAdt") {
            if (type === "def-" + v.type) return true;
            // TODO: add matchesTraits here when traits are implemented
        }
    };

    return false;
}

class StructType {
    customId = "vgsAdt"
    kind = "struct"

    constructor(definitionId) {
        this.definition = typeDefinitions[definitionId];
        this.type = definitionId;

        if (this.definition.kind !== "struct") throw new Error("Expected struct type");

        this.fields = Object.create(null);
        /**
         * Traits:
         * {
         *     trait: TRAIT_ID,
         *     impl: IMPLEMENTATION
         * }  
         */
        this.traits = [];
        this.impl = {};
    }

    static clone(self) {
        const clone = new this(self.type);
        clone.fields = self.fields;
        clone.traits = self.traits;
        clone.impl = self.impl;
        return clone;
    }

    static fromBuilder(definitionId, fields) {
        const self = new this(definitionId);
        fields.forEach(([k, v]) => {
            self.setField(k, v);
        })
        return self;
    }

    static getField(struct, field, needsValidation) {
        if (!disableRuntimeChecks && needsValidation) {
            if (!struct.definition.fields[field]) throw new Error("Attempted to get field " + field + " on a struct whose definition does not include it");
        }
        return struct.fields[field];
    }

    static setField(struct, field, value, needsValidation, valNeedsValidation, isMutableOperation) {
        if (!(struct instanceof StructType)) throw new Error("Cannot set field on non-struct.");
        if (!disableRuntimeChecks && isMutableOperation) {
            if (struct.definition.immutable) throw new Error("Cannot mutate immutable struct type. Use the copy with field block instead.")
        }
        if (!disableRuntimeChecks && needsValidation) {
            // validate that the key is valid
            if (!struct.definition.fields[field]) throw new Error("Attempted to set field " + field + " on a struct whose definition does not include it");
        }
        if (!disableRuntimeChecks && valNeedsValidation) {
            const thing = struct.definition.fields[field];
            if (!thing) throw new Error("Attempted to set field " + field + " on a struct whose definition does not include it")
            if (!matchesType(value, thing.valueType, thing.valuePenguinmodType)) throw new Error("Attempted to set field " + field + " to a value that does not match the type on the struct definition.")
        }
        return struct.fields[field] = value, struct;
    }

    setField(k, v) {
        if (disableRuntimeChecks) {
            this.fields[k] = v;
            return;
        }
        const fields = this.definition.fields;
        if (!Object.hasOwn(fields, k)) throw new Error("Key not present in struct definition");
        const thing = fields[k];
        if (!matchesType(v, thing.valueType, thing.valuePenguinmodType)) throw new Error("Type does not match required type")
        this.fields[k] = v
    }

    [pmSymbol.equals](other) {
        return false; // TODO: actually handle this
    }
}

class EnumType {
    customId = "vgsAdt"
    kind = "enum"

    constructor(definitionId, variant = null) {
        this.definition = typeDefinitions[definitionId];
        this.type = definitionId;

        console.log(this.definition, variant)

        if (this.definition.kind !== "enum") throw new Error("Expected enum type");

        this.value = null;
        if (!Object.keys(this.definition.variants).includes(variant)) throw new Error("Invalid enum variant " + variant + " of enum " + this.definition.name);
        this.variant = variant;
        /**
         * Traits:
         * {
         *     trait: TRAIT_ID,
         *     impl: IMPLEMENTATION
         * }  
         */
        this.traits = [];
        this.impl = {};
    }

    static clone(self) {
        const clone = new this(self.type, self.variant);
        clone.value = self.value;
        clone.traits = self.traits;
        clone.impl = self.impl;
        return clone;
    }

    // runtime utils
    static createEnum(typedefId, variant, value) {
        const res = new EnumType(typedefId, variant);
        if (value != null) res.setValue(value);
        return res;
    }

    static checkVariant(typedefId, variant, value) {
        if (value instanceof EnumType) {
            return value.type === typedefId && value.variant === variant
        };
        return false;
    }

    static unwrapVariant(typedefId, variant, value) {
        if (value instanceof EnumType) {
            if (value.type === typedefId && value.variant === variant) return value.value;
            throw new Error("Failed to unwrap enum " + value.definition.name + "::" + value.variant);
        };
        throw new Error("Attempted to unwrap a non-enum?");
    }

    static unwrapVariantOr(typedefId, variant, value, fallback, needsValidation) {
        if (needsValidation && !disableRuntimeChecks) {
            const variantTypes = typeDefinitions[typedefId].variants[variant];
            if (!matchesType(fallback, variantTypes.valueType, variantTypes.valuePenguinmodType)) throw new Error("Value in the \"or\" part of this unwrap block should match the type in the type definition for this variant.");
        }
        if (value instanceof EnumType) {
            if (value.type === typedefId && value.variant === variant) return value.value;
            //throw new Error("Failed to unwrap enum " + value.definition.name + "::" + value.variant);
            return fallback;
        };
        throw new Error("Attempted to unwrap a non-enum?");
    }

    setValue(v) {
        if (disableRuntimeChecks) {
            this.value = v;
            return;
        }
        const variant = this.definition.variants[this.variant];
        if (!variant.holdsValue) throw new Error("Enum variant does not support holding a value")
        console.log(variant);
        if (!matchesType(v, variant.valueType, variant.valuePenguinmodType)) throw new Error("Type does not match required type")
        this.value = v;
    }

    [pmSymbol.equals](other) {
        return false; // TODO: actually handle this
    }
}

