                                        const holdsValue = typeDefinitions[node.typedefId].variants[node.variant].holdsValue;
                                        src += `case(vm.vgsEnum.Type.checkVariant("${node.typedefId}", "${node.variant}", DESTRUCTURED_VALUE)):{`;
