    resolveUniqueKey(targetMap, baseName) {
        if (!targetMap.hasOwnProperty(baseName)) {
            return { finalName: baseName, didConflict: false };
        }

        let n = 1;
        let newName = `${baseName}_${n}`;

        while (targetMap.hasOwnProperty(newName)) {
            n++;
            newName = `${baseName}_${n}`;
        }

        return { finalName: newName, didConflict: true };
    }

    countTypeDefEntries(type) {
        switch (type) {
            case "Structs":
                return Object.values(typeDefinitions).reduce((acc, v) => (v.kind === "struct" && !v.internal) ? acc + 1 : acc, 0)
            case "Enums":
                return Object.values(typeDefinitions).reduce((acc, v) => (v.kind === "enum" && !v.internal) ? acc + 1 : acc, 0)
            case "Traits":
                return Object.values(traitDefinitions).reduce((acc, v) => !v.internal ? acc + 1 : acc, 0)
        }
    }

