    generateDropdownElement(groupedOptions, initialValue) {
        const wrapper = document.createElement("div");
        wrapper.className = "custom-dropdown-wrapper";
        wrapper.style.display = "inline-block";
        wrapper.style.fontFamily = "inherit";

        const button = document.createElement("button");
        button.type = "button";

        button.style.width = "180px";
        button.style.display = "flex";
        button.style.justifyContent = "space-between";
        button.style.alignItems = "center";
        button.style.textAlign = "left";
        button.style.whiteSpace = "nowrap";
        button.style.overflow = "hidden";
        button.style.textOverflow = "ellipsis";
        button.style.padding = "6px 10px";
        button.style.cursor = "pointer";

        const buttonText = document.createElement("span");
        buttonText.style.whiteSpace = "nowrap";
        buttonText.style.overflow = "hidden";
        buttonText.style.textOverflow = "ellipsis";
        buttonText.style.marginRight = "10px";

        const buttonArrow = document.createElement("span");
        buttonArrow.textContent = "▼";
        buttonArrow.style.fontSize = "10px";

        button.appendChild(buttonText);
        button.appendChild(buttonArrow);
        wrapper.appendChild(button);

        const dropdown = document.createElement("div");
        dropdown.className = "fixed-dropdown-panel";
        dropdown.style.display = "none";
        dropdown.style.position = "fixed";
        dropdown.style.zIndex = "99999";
        dropdown.style.background = "#1e1e2e";
        dropdown.style.border = "1px solid #45475a";
        dropdown.style.width = "200px";
        dropdown.style.maxHeight = "180px";
        dropdown.style.overflowY = "auto";
        dropdown.style.boxShadow = "0px 4px 12px rgba(0,0,0,0.5)";

        document.body.appendChild(dropdown);

        const updatePosition = () => {
            const rect = button.getBoundingClientRect();
            dropdown.style.left = `${rect.left}px`;

            const spaceBelow = window.innerHeight - rect.bottom;
            const dropdownHeight = 180;

            if (spaceBelow < dropdownHeight && rect.top > dropdownHeight) {
                dropdown.style.top = `${rect.top - dropdown.offsetHeight}px`;
            } else {
                dropdown.style.top = `${rect.bottom}px`;
            }
        };

        const closeDropdown = () => {
            dropdown.style.display = "none";
        };

        button.onclick = (e) => {
            e.stopPropagation();
            const isOpen = dropdown.style.display === "block";

            document.querySelectorAll(".fixed-dropdown-panel").forEach(p => {
                if (p !== dropdown) p.style.display = "none";
            });

            if (!isOpen) {
                dropdown.style.display = "block";
                updatePosition();
            } else {
                closeDropdown();
            }
        };

        window.addEventListener("scroll", updatePosition, { passive: true });
        window.addEventListener("resize", updatePosition);
        document.addEventListener("click", closeDropdown);

        const destroy = () => {
            window.removeEventListener("scroll", updatePosition);
            window.removeEventListener("resize", updatePosition);
            document.removeEventListener("click", closeDropdown);
            if (dropdown.parentNode) {
                dropdown.parentNode.removeChild(dropdown);
            }
            observer.disconnect();
        };

        const observer = new MutationObserver(() => {
            if (!wrapper.isConnected) {
                destroy();
            }
        });

        observer.observe(document.body, { childList: true, subtree: true });

        const categoryMapping = [
            { key: "default", label: null },
            { key: "regular", label: "Regular Types" },
            { key: "penguinmod", label: "PenguinMod Types" },
            { key: "struct", label: "Structs" },
            { key: "enums", label: "Enums" }
        ];

        let currentSelectionValue = null;
        let initialValueFound = false;

        const selectOption = (opt) => {
            currentSelectionValue = opt.value;
            buttonText.textContent = opt.text;
            closeDropdown();
        };

        categoryMapping.forEach(({ key, label }) => {
            const items = groupedOptions[key];
            if (!items || items.length === 0) return;

            let targetContainer = dropdown;

            if (label) {
                const details = document.createElement("details");
                details.style.borderBottom = "1px solid #313244";
                details.open = false;

                const summary = document.createElement("summary");
                summary.textContent = label;
                summary.style.cursor = "pointer";
                summary.style.padding = "4px 8px";
                summary.style.fontWeight = "bold";
                summary.style.background = "#11111b";
                summary.style.color = "#a6adc8";

                summary.onclick = (e) => {
                    e.stopPropagation();
                    setTimeout(updatePosition, 10);
                };

                const listContent = document.createElement("div");
                listContent.style.paddingLeft = "10px";

                details.appendChild(summary);
                details.appendChild(listContent);
                dropdown.appendChild(details);
                targetContainer = listContent;
            }

            items.forEach((opt) => {
                const optionDiv = document.createElement("div");
                optionDiv.textContent = opt.text;
                optionDiv.style.padding = "4px 8px";
                optionDiv.style.cursor = "pointer";
                optionDiv.style.color = "#cdd6f4";
                optionDiv.style.whiteSpace = "nowrap";

                optionDiv.onmouseover = () => { optionDiv.style.background = "#313244"; };
                optionDiv.onmouseout = () => { optionDiv.style.background = "transparent"; };

                optionDiv.onclick = (e) => {
                    e.stopPropagation();
                    selectOption(opt);
                };

                targetContainer.appendChild(optionDiv);

                if (initialValue === opt.value?.value) {
                    selectOption(opt);
                    initialValueFound = true;
                }
            });
        });

        if (initialValue && !initialValueFound) {
            selectOption({
                text: "??? (type got deleted?)",
                value: { valueType: "unknown" }
            });
        } else if (!currentSelectionValue && groupedOptions.default?.length > 0) {
            selectOption(groupedOptions.default[0]);
        }

        return {
            el: wrapper,
            getCurValue: () => currentSelectionValue,
            destroy
        };
    }

